+    QStringList mru =
+        settings_.value(QStringLiteral("dialogs/mru/") + purpose)
+            .toStringList();
+    mru.removeAll(dir);
+    mru.prepend(dir);
+    while (mru.size() > kMaxMruDirs) {
+        mru.removeLast();
+    }
+    settings_.setValue(QStringLiteral("dialogs/mru/") + purpose, mru);
+}
